import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"CS [4xxx]/[5xxx] Engineering Software with AI","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),n={name:"SYLLABUS.md"};function i(o,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="cs-4xxx5xxx-engineering-software-with-ai" tabindex="-1">CS [4xxx]/[5xxx] Engineering Software with AI <a class="header-anchor" href="#cs-4xxx5xxx-engineering-software-with-ai" aria-label="Permalink to &quot;CS [4xxx]/[5xxx] Engineering Software with AI&quot;">​</a></h1><p>3 credits</p><p>[Semester and year, as scheduled]</p><h2 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h2><ul><li><strong>Name:</strong> [name]</li><li><strong>Email:</strong> [email]</li><li><strong>Phone:</strong> [phone]</li><li><strong>Office hours:</strong> [days, times and place]</li><li><strong>Class meetings:</strong> [days, times and room]; two 75-minute meetings a week, a Seminar and a Lab</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>CS 3383 Software Engineering. The course builds on its requirements, design, testing and team practices and does not teach them again. Students should be comfortable with git, the command line, and Python or JavaScript. No experience with coding agents is needed, and the lower-division course <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/" target="_blank" rel="noreferrer">Building Apps with AI</a> is not a prerequisite.</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to &quot;Course Description&quot;">​</a></h2><p>This course examines how software is engineered when coding agents write much of the code. Students learn how large language model (LLM) coding agents work, how to give them context through specifications, <code>AGENTS.md</code> files and the Model Context Protocol (MCP), and how to secure them. The course then covers spec-driven development, tests as oracles and measured test adequacy, changes to legacy code, code review at scale, supply-chain security, LLM-based features and their evaluation, parallel and background agents, and the published evidence on AI in software engineering. Each week pairs a Seminar with a hands-on Lab. The Seminar introduces the week&#39;s concepts through a short talk, a live demonstration and a discussion or debate of the week&#39;s reading. The Lab is guided, hands-on work with that week&#39;s techniques, ending with a checkoff of each student&#39;s work. Throughout the semester, teams work in a class fork of a real open-source codebase: they specify contributions, delegate parts of the work to agents, and verify the results to the standard a maintainer would expect. Grades rest on evidence of verification and on each student&#39;s ability to explain their own work without AI.</p><h2 id="required-textbooks-and-materials" tabindex="-1">Required Textbooks and Materials <a class="header-anchor" href="#required-textbooks-and-materials" aria-label="Permalink to &quot;Required Textbooks and Materials&quot;">​</a></h2><p>No textbook. Weekly readings are listed in the <a href="./resources/reading-list.html">reading list</a>.</p><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning Outcomes&quot;">​</a></h2><p>At the end of this course, students will be able to:</p><ul><li>Explain how LLM coding agents work, including the model, context, tools, the agent loop, permissions and sandboxes, and run, read and extend a minimal agent.</li><li>Apply context engineering through specifications, <code>AGENTS.md</code> files and MCP tools, and measure whether agents follow them.</li><li>Evaluate AI-written code with tests whose adequacy is measured by property-based and mutation testing and enforced in continuous integration, and review AI-authored pull requests, AI reviewers and static analysis against known defects.</li><li>Change large existing codebases safely through comprehension, characterization tests and refactoring, and contribute changes that reviewers accept.</li><li>Analyze and reduce the security risks of AI-assisted development, including prompt injection, supply-chain attacks, leaked secrets and excessive permissions, and act responsibly toward users, maintainers and licenses.</li><li>Build and evaluate LLM-based features with structured outputs and calibrated evals, accounting for cost and latency, and assess published evidence about AI in software engineering.</li></ul><h2 id="course-outline" tabindex="-1">Course Outline <a class="header-anchor" href="#course-outline" aria-label="Permalink to &quot;Course Outline&quot;">​</a></h2><p>The course follows a standard 16-week semester. Weeks 1–15 have a Seminar and a Lab each week; week 16 is finals week, when teams present their projects in the scheduled final exam period.</p><table tabindex="0"><thead><tr><th>Week</th><th>Topic</th><th>Key concepts</th></tr></thead><tbody><tr><td>1</td><td><a href="./weeks/01-agentic-engineering/">From Vibe Coding to Agentic Engineering</a></td><td>Vibe coding versus agentic engineering; Specify, Delegate, Verify; observed and inferred claims; tokens, context and sampling; tool calling; the agent loop</td></tr><tr><td>2</td><td><a href="./weeks/02-inside-agents/">Inside Real Agents</a></td><td>Harness architecture; how prompts and tool schemas are assembled; context management; approval prompts versus real boundaries; reading a large codebase outside in</td></tr><tr><td>3</td><td><a href="./weeks/03-context-engineering/">Context Engineering</a></td><td>The context window as the agent&#39;s whole world; context rot; <code>AGENTS.md</code>, rules and skills; MCP servers and tools; measuring compliance</td></tr><tr><td>4</td><td><a href="./weeks/04-securing-agents/">Securing Agents</a></td><td>Prompt injection; the lethal trifecta; tool poisoning; allowlists, approvals, egress blocks and sandboxes; secrets out of reach; threat models</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-driven-development/">Spec-Driven Development</a></td><td><code>SPEC.md</code>, <code>DESIGN.md</code> and <code>TASKS.md</code>; EARS acceptance criteria; edge cases; plan mode; agent-sized tasks; specs that change</td></tr><tr><td>6</td><td><a href="./weeks/06-tests-as-oracles/">Tests as Oracles</a></td><td>Test oracles; writing the check first; property-based testing and shrinking; biased generators; bug reports as reproductions</td></tr><tr><td>7</td><td><a href="./weeks/07-test-adequacy/">Measuring Test Adequacy</a></td><td>Coverage versus mutation score; mutants and survivors; equivalent mutants; how scores get gamed; what mutation score cannot show</td></tr><tr><td>8</td><td><a href="./weeks/08-legacy-code/">Legacy Code</a></td><td>Characterization and approval tests; seams; what &quot;behavior unchanged&quot; means; small green refactoring steps; the strangler fig</td></tr><tr><td>9</td><td><a href="./weeks/09-review-at-scale/">Review at Scale</a></td><td>Reviewing AI-authored pull requests; review burden; AI reviewers and precision; comments people act on; static analysis; CI gates</td></tr><tr><td>10</td><td><a href="./weeks/10-supply-chain/">Supply Chain and Secure Code</a></td><td>Insecure-but-working code; exploit tests; slopsquatting; dependency confusion; install scripts; secrets in git history; provenance and SBOMs</td></tr><tr><td>11</td><td><a href="./weeks/11-llm-features/">Building LLM Features</a></td><td>Structured outputs and validation; valid versus correct; retries and repair; tool calling; cost and latency budgets; retrieval basics</td></tr><tr><td>12</td><td><a href="./weeks/12-evals/">Evals</a></td><td>Evals as experiments; failure modes; calibrating an LLM judge with Cohen&#39;s kappa; regression gates in CI; thresholds as targets; benchmark limits</td></tr><tr><td>13</td><td><a href="./weeks/13-parallel-agents/">Parallel and Background Agents</a></td><td>Merge points; git worktrees; background and cloud agents; orchestration cost; conflicts that merge cleanly; governance controls</td></tr><tr><td>14</td><td><a href="./weeks/14-evidence-and-responsibility/">Evidence and Responsibility</a></td><td>Measured versus perceived productivity; study design; contributor AI policies; disclosure over detection; licensing and provenance; a structured debate</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-and-reflect/">Ship and Reflect</a></td><td>Where the field is going; verification as the work; changing norms; integration sprint; presentation dry run; graduate study talks</td></tr><tr><td>16</td><td><a href="./weeks/16-final-presentations/">Final Presentations</a> (finals week)</td><td>Team presentations with a live demo in the scheduled final exam period; the final project is due</td></tr></tbody></table><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to &quot;Grading&quot;">​</a></h2><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>CS [4xxx]</th><th>CS [5xxx]</th></tr></thead><tbody><tr><td>Labs and assignments</td><td>35%</td><td>25%</td></tr><tr><td>Quizzes, reading responses and participation</td><td>15%</td><td>10%</td></tr><tr><td>Oral exams</td><td>15%</td><td>15%</td></tr><tr><td>Final project (team project)</td><td>35%</td><td>30%</td></tr><tr><td>Graduate work</td><td>—</td><td>20%</td></tr></tbody></table><p>Grades are based on evidence: commit history, the AI log (<code>AI_LOG.md</code>), checks that anyone can reproduce, and explanations given without AI. Labs and assignments, the final project and the graduate work are graded with the rubrics in the <a href="./assessment/">assessment guide</a>, which also has the rules for the quizzes and the oral exams.</p><h3 id="final-examination" tabindex="-1">Final Examination <a class="header-anchor" href="#final-examination" aria-label="Permalink to &quot;Final Examination&quot;">​</a></h3><p>There is no final examination. In the scheduled final exam period, each team gives a ten-minute presentation of its contribution with a live demo. The final project is due at the start of that period: the team&#39;s work in the class fork with its tests, a short final report, and each member&#39;s peer evaluation. The CS [5xxx] study paper is due at the same time.</p><h3 id="performance-standards-and-grading-policy" tabindex="-1">Performance Standards and Grading Policy <a class="header-anchor" href="#performance-standards-and-grading-policy" aria-label="Permalink to &quot;Performance Standards and Grading Policy&quot;">​</a></h3><p>Letter grades are A (90–100%), B (80–89%), C (70–79%), D (60–69%) and F (below 60%).</p><h3 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h3><ul><li>Labs and assignments (weeks 1–13): a Lab checkoff and a take-home assignment each week, due before the next week&#39;s Seminar. In weeks 9 and 10, each student also opens a pull request on another team&#39;s fork (<a href="./project/pr-round.html">the PR round</a>).</li><li>Quizzes, reading responses and participation: a short quiz without AI at the start of the Seminar in weeks 2–14 (<a href="./assessment/quizzes.html">quizzes</a>), a 150- to 250-word response to each week&#39;s reading, also without AI, and taking part in the Seminar.</li><li>Oral exams (weeks 8 and 14): two individual 15-minute exams without AI (<a href="./assessment/oral-exams.html">oral exams</a>).</li><li>The final project, or <a href="./project/">team project</a>: teams of three or four work in a class fork of a real open-source codebase all semester, with milestones in weeks 5, 8 and 12 and the final presentation in finals week.</li><li>Graduate work (CS [5xxx] only): a paper presentation with a turn as discussant, a critique or tool experience report, and a small empirical study, described under <a href="#graduate-students-cs-5xxx">Graduate Students</a> below.</li></ul><p>Reading responses, reflections, peer evaluations, the final report and graduate writing are submitted on Canvas, not in a repository.</p><h3 id="late-work-policy" tabindex="-1">Late Work Policy <a class="header-anchor" href="#late-work-policy" aria-label="Permalink to &quot;Late Work Policy&quot;">​</a></h3><p>Each student has two grace tokens, each extending one individual deadline by 48 hours, and each team has one token for one of its three milestones. Other late work loses 10% per day and scores zero after three days. Tokens do not apply to quizzes, oral exams, the PR round or the final presentations; missed live events follow the <a href="./assessment/#absences-and-make-up-work">make-up rules</a>.</p><h2 id="undergraduate-and-graduate-course-expectations" tabindex="-1">Undergraduate and Graduate Course Expectations <a class="header-anchor" href="#undergraduate-and-graduate-course-expectations" aria-label="Permalink to &quot;Undergraduate and Graduate Course Expectations&quot;">​</a></h2><p>CS [4xxx] and CS [5xxx] students attend the same Seminars and Labs and complete the same core work: labs and assignments, quizzes, both oral exams and the team project. Teams may include students from both levels. As the catalog requires for joint-listed courses, graduate students also complete additional work, presenting and critiquing research and running an empirical study of their own, so the shared components carry less weight in the CS [5xxx] grade.</p><h3 id="undergraduate-students-cs-4xxx" tabindex="-1">Undergraduate Students (CS [4xxx]) <a class="header-anchor" href="#undergraduate-students-cs-4xxx" aria-label="Permalink to &quot;Undergraduate Students (CS [4xxx])&quot;">​</a></h3><p>Undergraduates complete the shared work, weighted as in the CS [4xxx] column above. In weeks with a graduate paper presentation, they post one question about the paper on Canvas before the Seminar, written without AI; this counts toward participation. Expect about 8.5 hours of work a week: two 75-minute meetings and about six hours outside class.</p><h3 id="graduate-students-cs-5xxx" tabindex="-1">Graduate Students (CS [5xxx]) <a class="header-anchor" href="#graduate-students-cs-5xxx" aria-label="Permalink to &quot;Graduate Students (CS [5xxx])&quot;">​</a></h3><p>Graduate students complete the shared work and about 1.5 more hours a week of graduate work, worth 20% of their grade (<a href="./graduate/">graduate work</a>):</p><ul><li>a 20-minute presentation of a paper from the graduate seminar list, and one turn as discussant (5%);</li><li>a critique of one paper in about 1,000 words, or a tool experience report, due before the week 13 Seminar (5%);</li><li>a small empirical study, alone or in a pair, that replicates or extends published work, presented in week 15 and written up as a four- to six-page paper in ACM format, due in finals week (10%). Studies may not involve human subjects without IRB approval.</li></ul><p>In addition to the common outcomes, graduate students will be able to:</p><ul><li>Analyze and present research in AI for software engineering, judging what a paper shows, how strong its evidence is and what it means for practice.</li><li>Design and run a small empirical study and report it in a short paper.</li></ul><h2 id="ai-use" tabindex="-1">AI Use <a class="header-anchor" href="#ai-use" aria-label="Permalink to &quot;AI Use&quot;">​</a></h2><p>AI tools are a required part of this course. Students direct coding agents and are graded on whether they can specify, verify, secure and explain the result; work a student cannot explain does not count as their own. Each task is labelled AI on, AI limited or AI off; quizzes, oral exams, reading responses, reflections, peer evaluations and graduate critiques are always AI off. AI help is disclosed in <code>AI_LOG.md</code>, in an <code>Assisted-by: [tool and model]</code> line in commit messages, and in each pull request. The full rules are in the <a href="./assessment/#ai-use-policy">AI use policy</a> and the <a href="./setup/safety-contract.html">agent safety contract</a>.</p><h2 id="academic-honesty" tabindex="-1">Academic Honesty <a class="header-anchor" href="#academic-honesty" aria-label="Permalink to &quot;Academic Honesty&quot;">​</a></h2><p>Academic dishonesty, including cheating and plagiarism, is not tolerated at the University of Idaho. Plagiarism means presenting another&#39;s work as your own: copying it, quoting or paraphrasing it without attribution, or buying it. In this course it also includes using AI on a task marked AI off and hiding AI help that the <a href="#ai-use">AI Use</a> rules ask you to disclose. Suspected cases are handled under the Student Code of Conduct (FSH 2300) and reported to the Dean of Students.</p><h2 id="university-of-idaho-classroom-learning-civility-clause" tabindex="-1">University of Idaho Classroom Learning Civility Clause <a class="header-anchor" href="#university-of-idaho-classroom-learning-civility-clause" aria-label="Permalink to &quot;University of Idaho Classroom Learning Civility Clause&quot;">​</a></h2><p>Everyone in this course, including students, instructors, teaching assistants and guests, is expected to treat one another with respect and civility. If you feel our classroom does not meet this standard, please talk to me during office hours, or contact the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a>, the <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a> or the <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a>.</p><h2 id="center-for-disability-access-and-resources" tabindex="-1">Center for Disability Access and Resources <a class="header-anchor" href="#center-for-disability-access-and-resources" aria-label="Permalink to &quot;Center for Disability Access and Resources&quot;">​</a></h2><p>Students with disabilities who need accommodations should contact the Center for Disability Access and Resources (CDAR) at <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">www.uidaho.edu/cdar</a> or 208-885-6307. Accommodations must be approved through CDAR before they are implemented.</p><h2 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h2><p>The University of Idaho bans firearms from its property, with limited exceptions. Holders of a valid Idaho enhanced concealed carry license may carry a firearm only if it stays concealed at all times; displaying it, other than in necessary self-defense, violates University policy. Report firearms on University property to local law enforcement by calling 911.</p><h2 id="student-resources" tabindex="-1">Student Resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student Resources&quot;">​</a></h2><p>The University of Idaho offers <a href="https://www.uidaho.edu/student-resources" target="_blank" rel="noreferrer">student resources</a> to support your learning, including:</p><ul><li><strong>SI-PASS:</strong> <a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">peer-led study sessions</a> for difficult courses.</li><li><strong>Library:</strong> databases and research help from librarians on the <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">UofI Library website</a>.</li><li><strong>Technology help:</strong> the <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a>, 208-885-4357, <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>.</li><li><strong>Writing support:</strong> one-on-one help at the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">Writing Center</a>, 208-885-6644.</li><li><strong>Student Success Program:</strong> free tutoring Sunday to Thursday, 2:00 to 10:00 pm, in the Wallace Residence Center basement, open to all students.</li><li><strong>Vandal Food Pantry:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free food and hygiene items</a>, open to all.</li><li><strong>Green Dot Safety Program:</strong> <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">bystander intervention training</a>; <a href="mailto:greendot@uidaho.edu" target="_blank" rel="noreferrer">greendot@uidaho.edu</a>.</li></ul><h2 id="uofi-moscow-land-acknowledgement" tabindex="-1">UofI Moscow Land Acknowledgement <a class="header-anchor" href="#uofi-moscow-land-acknowledgement" aria-label="Permalink to &quot;UofI Moscow Land Acknowledgement&quot;">​</a></h2><p>UofI Moscow is located on the homelands of the Nimiipuu (Nez Perce), Palus (Palouse) and Schitsu&#39;umsh (Coeur d&#39;Alene) tribes. We extend gratitude to the indigenous people that call this place home, since time immemorial. UofI recognizes that it is our academic responsibility to build relationships with the indigenous people to ensure integrity of tribal voices.</p>',54)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
